SCANNER_LOCK=pathlib.Path('runtime_state/oracle/final_boss_dual/scanner.lock')
REPORT=pathlib.Path('runtime_state/oracle/final_boss_dual/oracle_388_optimal_size_alignment.json')
class Hold(RuntimeError):pass

def sha(raw):return hashlib.sha256(raw.replace(b'\r\n',b'\n')).hexdigest()
def assets():
    items=json.loads(zlib.decompress(base64.b85decode(PAYLOAD.encode())).decode('utf-8'))
    if set(items)!=set(MANIFEST):raise Hold('EMBEDDED_ASSET_SET_MISMATCH')
    for k,v in items.items():
        if not isinstance(v,str) or sha(v.encode())!=MANIFEST[k]['after']:raise Hold('EMBEDDED_SOURCE_HASH_MISMATCH:'+k)
    return items

def audit():
    v=assets();s=v['qseries_v2/oracle_execution/solana_atomic_executor/boss_scanner_live.py']
    require=["SIZE_MIN_LAMPORTS=10_000_000", "SIZE_MAX_LAMPORTS=100_000_000",
             "SIZE_CURVE_SOL=tuple(round(0.010+i*0.005,3) for i in range(19))",
             "q20.FAST_SIZES=SIZE_CURVE_SOL", "'max() iterable argument is empty'", "choose_direction_best(tls.quote_rows)"]
    if any(x not in s for x in require):raise Hold('SCANNER_CURVE_OR_EMPTY_QUOTE_GUARD_MISSING')
    ingress=v['qseries_v2/oracle_execution/solana_atomic_executor/oracle_363_verified_scanner_bus_binding.py']
    if 'key = (token, direction)' not in ingress or 'guard.keep_latest(directional)' not in ingress:
        raise Hold('BIDIRECTIONAL_INGRESS_NOT_ISOLATED')
    if 'MIN_SIZE = 10_000_000' not in ingress or 'MAX_SIZE = 100_000_000' not in ingress:
        raise Hold('INGRESS_SIZE_WINDOW_MISMATCH')
    native=v['qseries_v2/oracle_execution/solana_atomic_executor/oracle_378_native_reverse_atomic.py']
    if "not 10_000_000<=size<=100_000_000" not in native:raise Hold('NATIVE_REVERSE_SIZE_WINDOW_MISMATCH')
    if 'DLMM_PARTIAL_FILL_REJECT' not in native or 'wsol_before<size' not in native:
        raise Hold('NATIVE_PROTECTION_MISSING')
    for name,src in v.items():
        if name.endswith('.py'):compile(src,name,'exec')
    print('[ORACLE388_SOURCE_AUDIT_PASS] files=11 size_range_SOL=0.010..0.100 size_step_SOL=0.005 directions=2 signing=False broadcasting=False',flush=True)

def plan():
    todo=[];current=[]
    for k,v in assets().items():
        p=pathlib.Path(k)
        if not p.is_file():raise Hold('EXPECTED_SOURCE_MISSING:'+k)
        h=sha(p.read_bytes());e=MANIFEST[k]
        if h==e['after']:current.append(k)
        elif h==e['before']:todo.append((p,v))
        else:raise Hold('UNEXPECTED_SOURCE_HASH_REFUSE_OVERWRITE:'+k)
    return todo,current

def verify():
    for k,e in MANIFEST.items():
        p=pathlib.Path(k)
        if not p.is_file() or sha(p.read_bytes())!=e['after']:raise Hold('VERIFY_SOURCE_HASH_MISMATCH:'+k)
    print('[ORACLE388_BYTE_VERIFIED] source_files=%d'%len(MANIFEST),flush=True)

def install():
    audit()
    if SCANNER_LOCK.exists():raise Hold('STOP_SCANNER_BEFORE_ORACLE388_INSTALL_NO_LOCK_DELETION')
    replacements,done=plan()   # ALL content fingerprints before ANY mutation
    staged=[]
    try:
        for dst,src in replacements:
            fd,tmp=tempfile.mkstemp(prefix='.oracle388.',dir=str(dst.parent))
            with os.fdopen(fd,'wb') as f:f.write(src.encode())
            staged.append((dst,pathlib.Path(tmp)))
        for dst,tmp in staged:os.replace(tmp,dst)
    finally:
        for _,tmp in staged:
            if tmp.exists():tmp.unlink()
    verify()
    REPORT.parent.mkdir(parents=True,exist_ok=True)
    obj={'build':'ORACLE388','size_min_sol':0.010,'size_max_sol':0.100,
         'scanner_optimizer_step_sol':0.005,'directional_ingress':True,
         'full_replacements':len(replacements),'already_current':len(done),
         'source_files':list(MANIFEST),'execution_authority':False,
         'signing':False,'broadcast':False,'private_key_used':False,
         'real_profit_certified':False}
    REPORT.write_text(json.dumps(obj,indent=2,sort_keys=True)+'\n',encoding='utf-8')
